function buildOrganizationJsonLd() {
  return {
    "@context": "https://schema.org",
    "@type": "Organization",
    name: "AISmallBiz",
    url: SITE_URL,
    logo: LOGO_URL,
    description: "Free AI help for small businesses: guides, workflows, and tools for Google Maps, social media, hiring, and daily operations.",
    sameAs: [SITE_URL]
  };
}
